protocol Mediator: AnyObject { func notify(_ sender: AnyObject, event: String) }

final class AuthDialog: Mediator {
    func notify(_ sender: AnyObject, event: String) {
        if sender === okButton, event == "click" { submit() }
    }
    private func submit() { /* validate fields, then accept */ }
}
final class SubmitButton {
    weak var mediator: Mediator?                       // no retain cycle
    func tap() { mediator?.notify(self, event: "click") }
}

