let center = NotificationCenter.default

let token = center.addObserver(forName: .authModeChanged, object: nil, queue: .main) { note in
    emailField.isEnabled = (note.userInfo?["checked"] as? Bool) == false
}
// producer, elsewhere:
center.post(name: .authModeChanged, object: nil, userInfo: ["checked": true])

// and later:
center.removeObserver(token)
